-- Minimal fixtures: run ONLY in a disposable, isolated database.
create table profiles(id uuid primary key, active boolean, role text);
create table contacts(id bigint primary key, deleted_at timestamptz, updated_at timestamptz);
create table event_invitations(id bigint primary key, event_id bigint, invitation_status text, updated_at timestamptz);
create table email_batches(id bigint generated by default as identity primary key, event_id bigint, template_id bigint, target_kind text, status text, recipient_count integer, include_public_response_link boolean, created_by_profile_id uuid);
create table email_batch_attachments(batch_id bigint, attachment_id bigint, primary key(batch_id,attachment_id));
create table email_logs(id bigint generated by default as identity primary key, batch_id bigint, event_id bigint, invitation_id bigint, contact_id bigint, template_id bigint, to_email text, subject text, rendered_text text, rendered_html text, status text, provider_message_id text);
